# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">UNIT 4: WILD ANIMALS — ANIMAL GROUPS AND HABITATS (E7.4)</text>\n  <rect x="22" y="48" width="155" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="99" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">1. Mammals (Memeliler)</text>\n  <text x="34" y="96" font-size="11" fill="#334155">• Lion / Tiger (Aslan/Kaplan)</text>\n  <text x="34" y="116" font-size="11" fill="#334155">• Elephant (Fil - tusks/trunk)</text>\n  <text x="34" y="136" font-size="11" fill="#334155">• Giraffe (Zürafa - long neck)</text>\n  <text x="34" y="156" font-size="11" fill="#334155">• Dolphin / Whale (Su memelisi)</text>\n  <text x="34" y="176" font-size="11" fill="#334155">• Bear / Rhino / Cheetah</text>\n  <text x="99" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Give birth &amp; feed with milk</text>\n  <rect x="188" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="265" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Reptiles (Sürüngenler)</text>\n  <text x="200" y="96" font-size="11" fill="#334155">• Crocodile / Alligator (Timsah)</text>\n  <text x="200" y="116" font-size="11" fill="#334155">• Snake (Yılan - poisonous)</text>\n  <text x="200" y="136" font-size="11" fill="#334155">• Lizard (Kertenkele)</text>\n  <text x="200" y="156" font-size="11" fill="#334155">• Turtle / Chameleon</text>\n  <text x="200" y="176" font-size="11" fill="#334155">• Cold-blooded &amp; scaly skin</text>\n  <text x="265" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Lay eggs (Yumurtlarlar)</text>\n  <rect x="354" y="48" width="155" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="431" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">3. Birds (Kuşlar)</text>\n  <text x="366" y="96" font-size="11" fill="#334155">• Eagle (Kartal - sharp claws)</text>\n  <text x="366" y="116" font-size="11" fill="#334155">• Falcon / Hawk (Şahin/Atmaca)</text>\n  <text x="366" y="136" font-size="11" fill="#334155">• Owl (Baykuş - hunts at night)</text>\n  <text x="366" y="156" font-size="11" fill="#334155">• Ostrich / Penguin (Uçamaz)</text>\n  <text x="366" y="176" font-size="11" fill="#334155">• Feathers, wings &amp; beak</text>\n  <text x="431" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">High in the mountains/sky</text>\n  <rect x="520" y="48" width="158" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="599" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">4. Habitats &amp; Diet</text>\n  <text x="532" y="96" font-size="11" fill="#334155">• Jungle / Rainforest (Orman)</text>\n  <text x="532" y="116" font-size="11" fill="#334155">• Desert (Çöl - camel, lizard)</text>\n  <text x="532" y="136" font-size="11" fill="#334155">• Ocean / Sea / River (Su)</text>\n  <text x="532" y="156" font-size="11" fill="#334155">• Savannah / Grasslands</text>\n  <text x="532" y="176" font-size="11" fill="#334155">• Carnivore (Etçil) / Herbivore</text>\n  <text x="599" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#9d174d">Omnivore (Hem etçil hem otçul)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DESCRIBING FREQUENCY AND MAKING INQUIRIES ABOUT WILDLIFE</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Adverbs of Frequency (Sıklık Zarfları)</text>\n  <text x="44" y="98" font-size="11.5" fill="#334155">• Always (100%): Lions always eat meat.</text>\n  <text x="44" y="122" font-size="11.5" fill="#334155">• Usually (80%): Tigers usually hunt alone.</text>\n  <text x="44" y="146" font-size="11.5" fill="#334155">• Often (60%): Eagles often build nests high.</text>\n  <text x="44" y="170" font-size="11.5" fill="#334155">• Sometimes (40%): Bears sometimes eat fish.</text>\n  <text x="44" y="194" font-size="11.5" fill="#334155">• Never (0%): Herbivores never eat meat.</text>\n  <text x="183" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">How often do they hunt? — Usually during the day.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Wh- Questions About Wild Animals</text>\n  <text x="378" y="98" font-size="11" fill="#334155">• Where do tigers live? — In Asia / jungles.</text>\n  <text x="378" y="122" font-size="11" fill="#334155">• What do giant pandas eat? — Bamboo.</text>\n  <text x="378" y="146" font-size="11" fill="#334155">• How much does an elephant weigh? — 5 tons.</text>\n  <text x="378" y="170" font-size="11" fill="#334155">• How long do tortoises live? — Over 100 years.</text>\n  <text x="378" y="194" font-size="11" fill="#334155">• Which animals are extinct? — Dinosaurs, dodos.</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Extinct (Soyu tükenmiş) vs. Endangered (Tehlikede)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MAKING SIMPLE SUGGESTIONS: SHOULD &amp; SHOULDN\'T (PROTECTING WILDLIFE)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">WE SHOULD + V1 (Yapmalıyız)</text>\n  <text x="44" y="100" font-size="11.5" fill="#334155">✓ We should protect wild animals and nature.</text>\n  <text x="44" y="124" font-size="11.5" fill="#334155">✓ We should save natural habitats and forests.</text>\n  <text x="44" y="148" font-size="11.5" fill="#334155">✓ We should plant more trees and keep seas clean.</text>\n  <text x="44" y="172" font-size="11.5" fill="#334155">✓ We should educate people about wildlife.</text>\n  <text x="44" y="196" font-size="11.5" fill="#334155">✓ We should vaccinate animals against diseases.</text>\n  <text x="183" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">What should we do to protect wildlife?</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">WE SHOULDN\'T + V1 (Yapmamalıyız)</text>\n  <text x="378" y="100" font-size="11.5" fill="#334155">✗ We shouldn\'t hunt animals for fur, skin or tusks.</text>\n  <text x="378" y="124" font-size="11.5" fill="#334155">✗ We shouldn\'t destroy or cut down forests.</text>\n  <text x="378" y="148" font-size="11.5" fill="#334155">✗ We shouldn\'t pollute air, water and environment.</text>\n  <text x="378" y="172" font-size="11.5" fill="#334155">✗ We shouldn\'t keep wild animals in cages or circuses.</text>\n  <text x="378" y="196" font-size="11.5" fill="#334155">✗ We shouldn\'t harm endangered species.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Past Reason: Dodos became extinct because people hunted them.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
